19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	};
28	
29	const quotePremium = (step: QuoteStep): number => {
30	  const policyBasePremium = step.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
31	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
32	  return policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE;
33	};
34	
35	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
36	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
37	});
